const DB_NAME = 'versa_inventario_demo';
const DB_VERSION = 2;
const stores = ['products', 'offers', 'shifts', 'closures', 'sales', 'movements', 'labels', 'users', 'settings'];
const seedProducts = [
  { id: 'p-arroz', name: 'Arroz', sku: 'ARZ-001', presentation: 'Paquete 1 Kg', unit: 'unidad', stock: 50, warehouse: 35, salesFloor: 15, priceCash: 700, priceTransfer: 720, cost: 560, minStock: 5 },
  { id: 'p-frijol', name: 'Frijol', sku: 'FRJ-001', presentation: 'Bolsa 1 kg', unit: 'unidad', stock: 8, warehouse: 4, salesFloor: 4, priceCash: 600, priceTransfer: 620, cost: 460, minStock: 5 },
  { id: 'p-pasta', name: 'Pasta de tomate', sku: 'PST-001', presentation: 'Lata', unit: 'unidad', stock: 42, warehouse: 30, salesFloor: 12, priceCash: 300, priceTransfer: 310, cost: 220, minStock: 8 },
];
const state = { role: 'owner', screen: 'home', warehouseTab: 'stock', products: [], offers: [], shifts: [], closures: [], sales: [], movements: [], labels: [], users: [], cart: [], query: '', reportDetails: false, labelIds: [], presentations: ['Paquete 1 Kg', 'Bolsa 1 kg', 'Lata', 'Botella'], units: ['unidad', 'kg', 'litro', 'caja', 'docena'], toast: '', assets: {}, db: null, tour: null, tourStep: 0, pdfPicker: null, menuOpen: false, helpRole: null };
const app = document.querySelector('#app');
const money = (value) => `${new Intl.NumberFormat('es-ES', { maximumFractionDigits: 2 }).format(Number(value || 0))} CUP`;
const dateText = (value = new Date()) => new Date(value).toLocaleDateString('es-CU');
const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[char]));
const statusText = { open: 'Caja abierta', pending_review: 'Pendiente de revisión', approved: 'Aprobado', rejected: 'Rechazado', pending: 'Pendiente', synced: 'Sincronizado' };
const statusLabel = (value) => statusText[value] || value;
const movementText = { incoming: 'Entrada', transfer: 'Paso a venta', loss: 'Pérdida', closing: 'Cierre diario' };
const movementLabel = (summary = '') => summary.replace(/^(incoming|transfer|loss|closing):/, (_, type) => `${movementText[type]}:`);
function id(prefix) { return `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`; }
function showToast(message) { state.toast = message; render(); clearTimeout(showToast.timer); showToast.timer = setTimeout(() => { state.toast = ''; document.querySelector('.toast')?.remove(); }, 2800); }
function openDb() { return new Promise((resolve, reject) => { const request = indexedDB.open(DB_NAME, DB_VERSION); request.onupgradeneeded = () => { const db = request.result; stores.forEach((name) => { if (!db.objectStoreNames.contains(name)) db.createObjectStore(name, { keyPath: 'id' }); }); }; request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error); }); }
function readAll(store) { return new Promise((resolve, reject) => { const req = state.db.transaction(store, 'readonly').objectStore(store).getAll(); req.onsuccess = () => resolve(req.result); req.onerror = () => reject(req.error); }); }
function put(store, value) { return new Promise((resolve, reject) => { const req = state.db.transaction(store, 'readwrite').objectStore(store).put(value); req.onsuccess = () => resolve(value); req.onerror = () => reject(req.error); }); }
async function reloadData() { const values = await Promise.all(stores.map(readAll)); state.products = values[0]; state.offers = values[1]; state.shifts = values[2]; state.closures = values[3]; state.sales = values[4]; state.movements = values[5]; state.labels = values[6]; state.users = values[7]; state.assets = values[8].find((x) => x.id === 'transfer_info') || {}; }
async function seed() {
  const existingProducts = await readAll('products');
  if (!existingProducts.length) {
    for (const product of seedProducts) await put('products', product);
  } else {
    for (const product of existingProducts) {
      const total = Math.max(0, Number(product.stock || 0));
      const hadSplit = Number.isFinite(product.warehouse) || Number.isFinite(product.salesFloor);
      const migratedWithoutSplit = Number(product.salesFloor || 0) === 0 && Number(product.warehouse || 0) === total && total > 0;
      const warehouse = migratedWithoutSplit ? Math.ceil(total * 0.7) : (hadSplit ? Number(product.warehouse || 0) : Math.ceil(total * 0.7));
      const salesFloor = hadSplit && Number(product.salesFloor || 0) > 0 ? Number(product.salesFloor) : Math.max(0, total - warehouse);
      await put('products', { ...product, sku: product.sku || `SKU-${product.id.replace(/[^a-z0-9]/gi, '').slice(-6)}`, unit: product.unit || 'unidad', warehouse, salesFloor, cost: Number(product.cost || 0), minStock: Number(product.minStock || 0), priceTransfer: Number(product.priceTransfer || product.priceCash || 0) });
    }
  }
  if (!(await readAll('users')).length) await put('users', { id: 'user-leidis', name: 'Leidis', email: 'leidis@demo.local', role: 'Dependiente', point: 'Área de venta principal' });
  if (!(await readAll('shifts')).length) await put('shifts', { id: 'shift-demo', dependent: 'Leidis', status: 'approved', openingCash: 0, expectedCash: 0, declaredCash: 0, declaredTransfer: 0, difference: 0, date: '2026-10-10' });
  if (!(await readAll('settings')).length) await put('settings', { id: 'tour', completed: false });
  await reloadData();
}
function navItems() { return state.role === 'owner' ? [['home', 'Inicio'], ['products', 'Productos'], ['warehouse', 'Almacén'], ['salesFloor', 'Área de venta'], ['labels', 'Etiquetas QR'], ['offers', 'Ofertas'], ['closures', 'Cierres'], ['reports', 'Reportes'], ['users', 'Usuarios'], ['sync', 'Sincronización'], ['help', 'Ayuda']] : [['pos', 'Venta'], ['cash', 'Caja'], ['closeShift', 'Cierre diario'], ['sync', 'Sincronización'], ['help', 'Ayuda']]; }
function navButton([key, label]) { return `<button class="${state.screen === key ? 'active' : ''}" data-nav="${key}">${label}</button>`; }
function header() { return `<header class="topbar"><div class="brand"><div class="brand-mark">V</div><div class="brand-copy"><div class="brand-name">Versa-Inventario</div><div class="brand-status">Versión demo</div></div></div><div class="role-switch"><button class="${state.role === 'owner' ? 'active' : ''}" data-role="owner">Dueño</button><button class="${state.role === 'dependent' ? 'active' : ''}" data-role="dependent">Dependiente</button></div></header>`; }
const navIcons = { home: '<path d="M3 11l9-7 9 7v9a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/>', warehouse: '<path d="M3 9l9-5 9 5v11H3z"/><path d="M8 20v-6h8v6"/>', reports: '<path d="M4 20V10M10 20V4M16 20v-8M22 20H2"/>', pos: '<circle cx="9" cy="20" r="1.5"/><circle cx="18" cy="20" r="1.5"/><path d="M2 3h3l2.5 12h11L21 7H6"/>', cash: '<rect x="2" y="6" width="20" height="12" rx="2"/><circle cx="12" cy="12" r="2.5"/>', closeShift: '<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>', menu: '<path d="M4 6h16M4 12h16M4 18h16"/>' };
const navIcon = (key) => `<svg viewBox="0 0 24 24" aria-hidden="true">${navIcons[key] || ''}</svg>`;
function primaryNav() { const keys = state.role === 'owner' ? ['home', 'warehouse', 'reports'] : ['pos', 'cash', 'closeShift']; return navItems().filter(([key]) => keys.includes(key)).map(([key, label]) => [key, key === 'salesFloor' ? 'Venta' : label.replace('Cierre diario', 'Cierre')]); }
function bottomNav() { const inMenu = !primaryNav().some(([key]) => key === state.screen); return `<nav class="bottom-nav" aria-label="Navegación principal">${primaryNav().map(([key, label]) => `<button class="${state.screen === key ? 'active' : ''}" data-nav="${key}">${navIcon(key)}<span>${label}</span></button>`).join('')}<button class="${inMenu ? 'active' : ''}" data-action="open-menu" aria-label="Abrir menú" aria-expanded="${state.menuOpen ? 'true' : 'false'}" aria-controls="side-drawer">${navIcon('menu')}<span>Menú</span></button></nav>`; }
function sideDrawer() { return `<div class="drawer-backdrop${state.menuOpen ? ' open' : ''}" data-action="close-menu"></div><aside id="side-drawer" class="side-drawer${state.menuOpen ? ' open' : ''}" aria-label="Menú" aria-hidden="${state.menuOpen ? 'false' : 'true'}"${state.menuOpen ? '' : ' inert'}><div class="drawer-head"><strong>${state.role === 'owner' ? 'Menú del dueño' : 'Menú del dependiente'}</strong><button class="drawer-close" data-action="close-menu" aria-label="Cerrar menú">×</button></div><div class="drawer-list">${navItems().map(navButton).join('')}</div></aside>`; }
function demoNotice() { return `<div class="demo-notice" role="note"><strong>Versión demo.</strong> No la uses para el trabajo real de tu negocio: los datos solo se guardan en este equipo. Para adquirir la versión oficial, contacta al <a href="https://wa.me/5356189395?text=Hola%2C%20quiero%20la%20versi%C3%B3n%20oficial%20de%20Versa-Inventario" target="_blank" rel="noopener noreferrer">+53 5618 9395</a>.</div>`; }
function layout(content) { const nav = navItems(); return `${header()}${demoNotice()}<div class="layout"><aside class="side-nav">${nav.map(navButton).join('')}</aside><main class="main">${content}</main></div>${bottomNav()}${sideDrawer()}${state.toast ? `<div class="toast">${escapeHtml(state.toast)}</div>` : ''}${state.tour ? tourModal() : ''}${state.pdfPicker ? pdfPickerModal() : ''}`; }
function pageHead(title, subtitle, action = '') { return `<div class="page-heading"><div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</div>`; }
function metric(label, value) { return `<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div></div>`; }
function productOptions(selected = '') { return `<option value="">Seleccionar producto</option>${state.products.map((p) => `<option value="${p.id}" ${p.id === selected ? 'selected' : ''}>${escapeHtml(p.name)} · ${escapeHtml(p.presentation)}</option>`).join('')}`; }
function panel(title, body, extra = '') { return `<section class="panel"><div class="panel-title"><h2>${title}</h2>${extra}</div>${body}</section>`; }
function home() { const units = state.products.reduce((sum, p) => sum + Number(p.stock || 0), 0); const pending = state.shifts.filter((s) => s.status === 'pending_review').length; const sales = state.sales.reduce((sum, s) => sum + Number(s.total || 0), 0); return `${pageHead('Inicio', 'Resumen sencillo de tu negocio.') }<div class="grid metrics">${metric('Ventas registradas', money(sales))}${metric('Productos', state.products.length)}${metric('Unidades', units)}${metric('Cierres pendientes', pending)}</div>${panel('Acciones rápidas', '<div class="grid quick-actions"><button class="button" data-nav="products">Crear producto</button><button class="button secondary" data-nav="warehouse">Entrada almacén</button><button class="button secondary" data-nav="offers">Oferta del día</button><button class="button secondary" data-nav="closures">Revisar caja</button></div>')}${panel('Últimas ventas', state.sales.length ? `<div class="list">${state.sales.slice(-6).reverse().map((s) => `<div class="list-row"><span>${escapeHtml(s.summary || 'Venta')}</span><strong>${money(s.total)}</strong></div>`).join('')}</div>` : '<div class="empty">Sin ventas registradas todavía.</div>')}`; }
function productForm(product = {}) { const presentation = product.presentation || state.presentations[0]; const unit = product.unit || state.units[0]; return `<form class="form-grid" data-form="product"><div class="field"><label>Nombre del producto</label><input class="input" name="name" required value="${escapeHtml(product.name || '')}" placeholder="Ej. Arroz" /></div><div class="field"><label>Código / SKU</label><input class="input" name="sku" value="${escapeHtml(product.sku || '')}" placeholder="Ej. ARZ-001" /></div><div class="field"><label>Presentación</label><select class="select" name="presentation" data-catalog-select="presentation">${state.presentations.map((item) => `<option ${item === presentation ? 'selected' : ''}>${escapeHtml(item)}</option>`).join('')}<option value="__new__">Añadir nueva presentación...</option></select></div><div class="field"><label>Unidad</label><select class="select" name="unit" data-catalog-select="unit">${state.units.map((item) => `<option ${item === unit ? 'selected' : ''}>${escapeHtml(item)}</option>`).join('')}<option value="__new__">Añadir nueva unidad...</option></select></div><div class="field"><label>Precio en efectivo</label><input class="input" name="priceCash" type="number" min="0" required value="${product.priceCash || ''}" /></div><div class="field"><label>Precio por transferencia</label><input class="input" name="priceTransfer" type="number" min="0" value="${product.priceTransfer || ''}" /></div><details class="advanced"><summary>Opciones avanzadas</summary><div class="form-grid"><div class="field"><label>Costo</label><input class="input" name="cost" type="number" min="0" value="${product.cost || ''}" /></div><div class="field"><label>Stock mínimo</label><input class="input" name="minStock" type="number" min="0" value="${product.minStock || 0}" /></div></div></details><button class="button" type="submit">${product.id ? 'Guardar cambios' : 'Guardar producto'}</button></form>`; }
function products() { const visible = state.products.filter((p) => !state.query || `${p.name} ${p.presentation} ${p.sku}`.toLowerCase().includes(state.query.toLowerCase())); return `${pageHead('Productos', 'Alta, edición y búsqueda del catálogo.', '<button class="button small" data-action="new-product">Nuevo producto</button>')}${state.productEditor ? panel(state.productEditor.id ? 'Editar producto' : 'Alta de producto', productForm(state.productEditor), '<button class="icon-button" data-action="close-editor">Cerrar</button>') : ''}${panel('Catálogo', `<div class="toolbar"><input class="input search" data-query placeholder="Buscar por nombre, SKU o presentación" value="${escapeHtml(state.query)}" /><span class="muted">${visible.length} resultado(s)</span></div><div class="list">${visible.length ? visible.map((p) => `<button class="list-row list-button" data-action="edit-product" data-id="${p.id}"><span><h3>${escapeHtml(p.name)}</h3><span class="muted">${escapeHtml(p.presentation)} · ${escapeHtml(p.unit)} · Stock: ${p.stock} · SKU: ${escapeHtml(p.sku)}</span></span><span class="price">${money(p.priceCash)}</span></button>`).join('') : '<div class="empty">No hay productos que coincidan.</div>'}</div>`)}`; }
function warehouse() { const tabs = [['stock', 'Existencias'], ['incoming', 'Entradas'], ['transfer', 'Pasar a venta'], ['loss', 'Pérdidas']]; const tabButtons = tabs.map(([key, label]) => `<button class="tab ${state.warehouseTab === key ? 'active' : ''}" data-warehouse-tab="${key}">${label}</button>`).join(''); let body = ''; if (state.warehouseTab === 'stock') body = `<div class="list">${state.products.map((p) => `<div class="list-row"><span><h3>${escapeHtml(p.name)}</h3><span class="muted">Almacén: ${p.warehouse} · Área de venta: ${p.salesFloor}</span></span><strong>${p.stock} en total</strong></div>`).join('')}</div>`; if (state.warehouseTab === 'incoming') body = warehouseForm('incoming', 'Registrar entrada', ['Proveedor', 'Código de lote', 'Cantidad', 'Vencimiento']); if (state.warehouseTab === 'transfer') body = warehouseForm('transfer', 'Pasar al área de venta', ['Lote / producto', 'Cantidad']); if (state.warehouseTab === 'loss') body = warehouseForm('loss', 'Registrar pérdida', ['Producto', 'Cantidad', 'Motivo']); return `${pageHead('Almacén', 'Organiza existencias, entradas, traslados y pérdidas.')}${panel('Secciones de almacén', `<div class="tabs">${tabButtons}</div>${body}`)}${panel('Regla de seguridad', '<div class="warning">La app no deja pasar al área de venta más de lo que hay en el almacén. Así se evitan descuadres.</div>')}`; }
function warehouseForm(type, title, fields) { const product = `<div class="field"><label>Producto</label><select class="select" name="warehouseProduct" data-warehouse-product>${productOptions()}</select></div>`; const rest = fields.filter((f) => !['Producto', 'Lote / producto'].includes(f)).map((f) => `<div class="field"><label>${f}</label><input class="input" name="${f.toLowerCase().replaceAll(' ', '-') }" type="${f === 'Cantidad' ? 'number' : 'text'}" placeholder="${f === 'Vencimiento' ? 'AAAA-MM-DD' : ''}" /></div>`).join(''); return `<div class="subpanel"><h3>${title}</h3>${product}${rest}<button class="button" data-action="warehouse-save" data-type="${type}">Guardar ${type === 'incoming' ? 'entrada' : type === 'transfer' ? 'traslado' : 'pérdida'}</button></div>`; }
function salesFloor() { return `${pageHead('Área de venta', 'Existencias listas para vender y movimientos del periodo.')}${panel('Inventario disponible', `<div class="list">${state.products.map((p) => `<div class="list-row"><span><h3>${escapeHtml(p.name)}</h3><span class="muted">Disponible para venta: ${p.salesFloor} · Precio: ${money(p.priceCash)}</span></span><span class="badge">${p.salesFloor > 0 ? 'Disponible' : 'Agotado'}</span></div>`).join('')}</div>`)}`; }
function labels() { const selected = state.products.filter((p) => state.labelIds.includes(p.id)); const visible = state.products.filter((p) => !state.query || `${p.name} ${p.sku}`.toLowerCase().includes(state.query.toLowerCase())); return `${pageHead('Etiquetas QR', 'Selecciona varios productos y prepara sus etiquetas internas.', '<button class="button small" data-action="print-labels" '+(!selected.length ? 'disabled' : '')+'>Generar etiquetas</button>')}${panel('Selección de productos', `<div class="toolbar"><input class="input search" data-query placeholder="Buscar producto o código" value="${escapeHtml(state.query)}" /><button class="button small secondary" data-action="select-all">${visible.length && visible.every((p) => state.labelIds.includes(p.id)) ? 'Quitar todos' : 'Seleccionar todos'}</button></div><p class="muted">${selected.length} producto(s) seleccionado(s).</p><div class="list">${visible.map((p) => `<label class="check-row"><input type="checkbox" data-label-id="${p.id}" ${state.labelIds.includes(p.id) ? 'checked' : ''} /><span>${escapeHtml(p.name)} · ${escapeHtml(p.presentation)} · ${escapeHtml(p.sku)}</span></label>`).join('')}</div>`) }${panel('Etiquetas guardadas', state.labels.length ? `<div class="list">${state.labels.slice(-10).reverse().map((l) => `<div class="list-row"><span>${escapeHtml(l.name)}</span><span class="muted">${dateText(l.createdAt)}</span></div>`).join('')}</div>` : '<div class="empty">Todavía no hay etiquetas guardadas.</div>')}`; }
function offers() { const current = state.offers[0] || {}; return `${pageHead('Ofertas del día', 'Elige un producto: los precios actuales se cargan para revisarlos antes de publicar.')}${panel('Oferta del día', `<div class="field"><label>Producto</label><select class="select" data-offer-product>${productOptions(current.productId)}</select></div><div class="form-grid"><div class="field"><label>Precio actual en efectivo</label><input class="input" data-offer-cash value="${current.priceCash || ''}" type="number" /></div><div class="field"><label>Precio actual por transferencia</label><input class="input" data-offer-transfer value="${current.priceTransfer || ''}" type="number" /></div><div class="field"><label>Precio de oferta en efectivo</label><input class="input" data-offer-sale-cash value="${current.offerCash || ''}" type="number" /></div><div class="field"><label>Precio de oferta por transferencia</label><input class="input" data-offer-sale-transfer value="${current.offerTransfer || ''}" type="number" /></div></div><div class="field"><label>Información de la oferta</label><textarea class="input" data-offer-message placeholder="Ej. Solo por hoy, máximo 3 unidades">${escapeHtml(current.message || '')}</textarea></div><div class="field"><label>Métodos de pago aceptados</label><div class="check-group"><label><input type="checkbox" data-pay="cash" ${current.payments?.cash === false ? '' : 'checked'} /> Efectivo</label><label><input type="checkbox" data-pay="transfer" ${current.payments?.transfer === false ? '' : 'checked'} /> Transferencia</label></div></div><button class="button" data-action="save-offer">Publicar oferta</button>`) }${panel('Información de cobros por transferencia', `<p class="muted">Selecciona una imagen o un PDF. Si es PDF, podrás abrirlo y marcar manualmente el marco del QR que quieres conservar.</p><div class="form-grid"><div class="field"><label>Número de cuenta</label><input class="input" data-asset="account" placeholder="Número de cuenta" value="${escapeHtml(state.assets.account || '')}" /></div><div class="field"><label>Teléfono de confirmación</label><input class="input" data-asset="phone" placeholder="Teléfono" value="${escapeHtml(state.assets.phone || '')}" /></div></div><div class="file-grid"><label class="file-card">QR de transferencia<input type="file" accept="image/*,.pdf" data-file="qr" /><span data-file-name="qr">Seleccionar imagen o PDF</span></label><label class="file-card">Foto del negocio<input type="file" accept="image/*" data-file="photo" /><span data-file-name="photo">Seleccionar foto</span></label></div><button class="button secondary" data-action="save-assets">Guardar información de cobros</button>`)}`; }
function closures() { return `${pageHead('Cierres de caja', 'Revisa el turno enviado por el dependiente y apruébalo o recházalo.')}${panel('Cierres recibidos', state.shifts.length ? `<div class="list">${state.shifts.slice().reverse().map((s) => `<div class="list-row"><span><h3>${escapeHtml(s.dependent || 'Dependiente')}</h3><span class="muted">${escapeHtml(s.date)} · Esperado: ${money(Number(s.expectedCash || 0) + Number(s.expectedTransfer || 0))} · Contado: ${money(Number(s.declaredCash || 0) + Number(s.declaredTransfer || 0))} · Diferencia: ${money(s.difference)}${s.notes ? ` · Nota: ${escapeHtml(s.notes)}` : ''}</span><br><span class="badge">${escapeHtml(statusLabel(s.status))}</span></span>${s.status === 'pending_review' ? `<span class="button-group"><button class="button small" data-action="approve" data-id="${s.id}">Aprobar</button><button class="button small danger" data-action="reject" data-id="${s.id}">Rechazar</button></span>` : '<span class="muted">Revisado</span>'}</div>`).join('')}</div>` : '<div class="empty">No hay cierres registrados.</div>')}`; }
function reports() { const total = state.sales.reduce((sum, s) => sum + Number(s.total || 0), 0); const byPayment = { cash: state.sales.filter((s) => s.payment === 'cash').length, transfer: state.sales.filter((s) => s.payment === 'transfer').length }; return `${pageHead('Reportes', 'Resumen visual primero. Muestra los datos detallados solo cuando los necesites.')}${panel('Resumen de ventas', `<div class="chart-grid"><div class="chart-card"><div class="chart-title">Ventas por día</div><div class="bar-chart"><i style="height:45%"></i><i style="height:70%"></i><i style="height:55%"></i><i style="height:88%"></i><i style="height:64%"></i></div></div><div class="chart-card"><div class="chart-title">Métodos de pago</div><div class="pie" style="--cash:${byPayment.cash || 5};--transfer:${byPayment.transfer || 3}"><span>Pago</span></div><div class="legend"><span>● Efectivo</span><span>● Transferencia</span></div></div></div><div class="grid metrics">${metric('Ventas', money(total))}${metric('Pérdidas', money(0))}${metric('Operaciones', state.sales.length)}${metric('Productos', state.products.length)}</div><button class="button secondary" data-action="toggle-details">${state.reportDetails ? 'Ocultar detalles' : 'Mostrar detalles'}</button>${state.reportDetails ? `<div class="details-table"><h3>Detalle de ventas</h3>${state.sales.length ? state.sales.map((s) => `<div class="list-row"><span>${escapeHtml(s.summary)}</span><strong>${money(s.total)}</strong></div>`).join('') : '<p class="muted">La demo inicia sin ventas reales.</p>'}<h3>Detalle de inventario</h3>${state.products.map((p) => `<div class="list-row"><span>${escapeHtml(p.name)}</span><strong>${p.stock} unidades</strong></div>`).join('')}</div>` : ''}`)}`; }
function users() { return `${pageHead('Usuarios', 'Crea accesos de dependientes y asígnalos a un punto de venta.', '<button class="button small" data-action="new-user">Nuevo usuario</button>')}${state.userEditor ? panel('Agregar dependiente', `<form class="form-grid" data-form="user"><div class="field"><label>Nombre</label><input class="input" name="name" required placeholder="Nombre del dependiente" /></div><div class="field"><label>Correo</label><input class="input" name="email" type="email" required placeholder="correo@ejemplo.com" /></div><div class="field"><label>Punto de venta</label><input class="input" name="point" value="Área de venta principal" /></div><button class="button">Crear dependiente</button></form>`) : ''}${panel('Usuarios registrados', `<div class="list">${state.users.map((u) => `<div class="list-row"><span><h3>${escapeHtml(u.name)}</h3><span class="muted">${escapeHtml(u.email)} · ${escapeHtml(u.point)}</span></span><span class="badge">${escapeHtml(u.role)}</span></div>`).join('')}</div>`)}`; }
function sync() { const pending = state.movements.filter((m) => m.status === 'pending').length; return `${pageHead('Sincronización', 'En esta demo las operaciones permanecen en este navegador.')}${panel('Estado local', `<div class="grid metrics">${metric('Pendientes', pending)}${metric('Guardadas', state.sales.length + state.movements.length)}${metric('Conflictos', 0)}</div><button class="button" data-action="sync">Sincronizar ahora</button><div class="list history">${state.movements.slice(-8).reverse().map((m) => `<div class="list-row"><span>${escapeHtml(movementLabel(m.summary))}</span><span class="badge">${escapeHtml(statusLabel(m.status))}</span></div>`).join('')}</div>`)}`; }
function pos() { const visible = state.products.filter((p) => p.salesFloor > 0 && (!state.query || `${p.name} ${p.presentation} ${p.sku}`.toLowerCase().includes(state.query.toLowerCase()))); const total = state.cart.reduce((sum, i) => sum + i.priceCash * i.quantity, 0); return `${pageHead('Venta', 'Busca el producto, añádelo y confirma el pago.')}${state.shifts.some((s) => s.status === 'open') ? '' : '<div class="warning">Caja cerrada: abre un turno antes de cobrar.</div>'}${panel('Productos disponibles', `<div class="toolbar"><input class="input search" data-query placeholder="Buscar producto o código" value="${escapeHtml(state.query)}" /><button class="button small secondary" data-action="scan">Escanear</button></div><div class="list">${visible.map((p) => `<button class="list-row list-button" data-action="add-cart" data-id="${p.id}"><span><h3>${escapeHtml(p.name)}</h3><span class="muted">${escapeHtml(p.presentation)} · Disponible: ${p.salesFloor}</span></span><span class="price">${money(p.priceCash)}</span></button>`).join('') || '<div class="empty">No hay productos disponibles.</div>'}</div>`) }${panel('Venta actual', state.cart.length ? `${state.cart.map((i) => `<div class="list-row"><span>${escapeHtml(i.name)} x ${i.quantity}</span><button class="button small secondary" data-action="remove-cart" data-id="${i.id}">Quitar</button></div>`).join('')}<div class="cart-total"><span>Total</span><strong>${money(total)}</strong></div><div class="field"><label>Forma de pago</label><select class="select" data-payment><option value="cash">Efectivo</option><option value="transfer">Transferencia</option><option value="mixed">Mixto</option></select></div><div class="form-grid"><input class="input" data-cash-payment type="number" placeholder="Efectivo recibido" /><input class="input" data-transfer-payment type="number" placeholder="Transferencia" /></div><button class="button" data-action="charge">Cobrar</button>` : '<div class="empty">Todavía no has añadido productos.</div>')}`; }
function cash() { const open = state.shifts.find((s) => s.status === 'open'); return `${pageHead('Caja', 'Abre el turno al comenzar y ciérralo al terminar.')}${panel(open ? 'Cerrar turno' : 'Abrir turno', `<p class="muted">${open ? 'Cuenta el efectivo, confirma transferencias y envía el cierre al dueño.' : 'Escribe el efectivo inicial que ya está en la caja.'}</p>${open ? '<div class="form-grid"><div class="field"><label>Efectivo contado</label><input class="input" data-cash type="number" min="0" value="0" /></div><div class="field"><label>Transferencias confirmadas</label><input class="input" data-transfer type="number" min="0" value="0" /></div><div class="field"><label>Gastos del turno</label><input class="input" data-expenses type="number" min="0" value="0" /></div><div class="field"><label>Retiros</label><input class="input" data-withdrawals type="number" min="0" value="0" /></div></div><div class="field"><label>Observaciones</label><textarea class="input" data-notes placeholder="Nota para el dueño"></textarea></div>' : '<div class="field"><label>Efectivo inicial</label><input class="input" data-opening type="number" min="0" value="0" /></div>'}<button class="button" data-action="cash-toggle">${open ? 'Enviar cierre al dueño' : 'Abrir caja'}</button>`)}`; }
function closeShift() { return `${pageHead('Cierre diario', 'Indica qué queda en el área de venta y su destino.')}${panel('Productos pendientes', `<div class="list">${state.products.map((p) => `<div class="subpanel"><h3>${escapeHtml(p.name)}</h3><div class="field"><label>Cantidad</label><input class="input" type="number" min="0" value="${p.salesFloor}" data-close-qty="${p.id}" /></div><div class="field"><label>Destino</label><select class="select" data-close-destination="${p.id}"><option value="warehouse">Devolver al almacén</option><option value="loss_merma">Merma</option><option value="loss_damage">Daño</option><option value="loss_other">Otro</option></select></div><input class="input" data-close-note="${p.id}" placeholder="Nota opcional" /></div>`).join('')}</div><button class="button" data-action="close-shift">Registrar cierre diario</button>`)}`; }
const helpGuide = {
  owner: [
    { key: 'home', title: 'Inicio: tu negocio de un vistazo', benefit: 'Al abrir la app ves cuánto has vendido, cuántos productos tienes y si hay cajas esperando tu revisión. Sin sacar cuentas a mano ni preguntar a nadie.', steps: ['Mira los cuatro números de arriba: ventas, productos, unidades y cierres pendientes.', 'Si «Cierres pendientes» es mayor que cero, toca «Revisar caja».', 'Usa los botones de «Acciones rápidas» para lo que haces todos los días.'], tip: 'Revísalo cada mañana: en un minuto sabes cómo fue el día anterior.' },
    { key: 'products', title: 'Productos: precios claros para todos', benefit: 'Cada producto queda con su precio en efectivo y por transferencia. Tus dependientes cobran siempre el precio correcto, aunque tú no estés en el negocio.', steps: ['Toca «Nuevo producto».', 'Escribe el nombre y los dos precios.', 'Toca «Guardar producto». Para cambiar un precio, toca el producto en la lista.'], tip: 'En «Opciones avanzadas» anota lo que te costó y el mínimo que quieres tener: así sabes cuánto ganas y cuándo reponer.' },
    { key: 'warehouse', title: 'Almacén: sabes qué tienes guardado', benefit: 'Separa lo que está guardado de lo que está en el mostrador. Si algo falta, sabes en qué paso se perdió.', steps: ['«Entradas»: cuando llega mercancía, anota cuánto llegó y de qué proveedor.', '«Pasar a venta»: cuando sacas mercancía al mostrador.', '«Pérdidas»: si algo se rompe o se vence, anótalo con el motivo.'], tip: 'La app no deja pasar al mostrador más de lo que hay guardado. Así se evitan descuadres.' },
    { key: 'salesFloor', title: 'Área de venta: lo que está listo para vender', benefit: 'Ves qué hay en el mostrador y qué se agotó antes de que un cliente lo pida y se vaya sin comprar.', steps: ['Revisa la lista de productos.', 'Los que dicen «Agotado» hay que sacarlos del almacén.', 'Ve a Almacén → «Pasar a venta» para reponerlos.'], tip: '' },
    { key: 'labels', title: 'Etiquetas QR: cobrar sin equivocarse', benefit: 'Pega una etiqueta en cada producto. El dependiente la escanea con el teléfono y el producto entra en la venta con su precio. Menos errores y colas más cortas.', steps: ['Marca los productos que necesitan etiqueta (o «Seleccionar todos»).', 'Toca «Generar etiquetas».', 'Imprímelas y pégalas en el producto o en el estante.'], tip: '' },
    { key: 'offers', title: 'Ofertas: mueve la mercancía que no sale', benefit: 'Publica la oferta del día con su precio especial. Tus dependientes la ven al momento y la cobran bien.', steps: ['Elige el producto: sus precios actuales aparecen solos.', 'Escribe el precio de oferta y, si quieres, una nota («Solo hoy»).', 'Marca cómo se puede pagar y toca «Publicar oferta».'], tip: 'Más abajo guarda tu número de cuenta y el QR de transferencia: tus clientes pagan sin tener que preguntarte.' },
    { key: 'closures', title: 'Cierres: la caja cuadra sin discusiones', benefit: 'Al terminar el turno, el dependiente envía lo que cobró. La app te dice cuánto debía haber, cuánto se contó y la diferencia. Se acabaron las cuentas en una libreta.', steps: ['Abre el cierre que envió el dependiente.', 'Si la diferencia es cero, toca «Aprobar».', 'Si no cuadra, toca «Rechazar» y conversa con el dependiente con los números delante.'], tip: '' },
    { key: 'reports', title: 'Reportes: decide con números, no a ojo', benefit: 'Ventas por día, cuánto te pagan en efectivo y cuánto por transferencia, y cuánto pierdes. Sabes qué funciona y qué no.', steps: ['Mira los gráficos: arriba, cómo van las ventas.', 'Abajo tienes el total vendido y las pérdidas.', 'Toca «Mostrar detalles» si quieres ver venta por venta.'], tip: '' },
    { key: 'users', title: 'Usuarios: cada dependiente con su acceso', benefit: 'Cada persona entra con su nombre. Siempre sabes quién vendió qué y en qué punto de venta.', steps: ['Toca «Nuevo usuario».', 'Escribe el nombre y el correo del dependiente.', 'Toca «Crear dependiente».'], tip: '' },
    { key: 'sync', title: 'Sincronización: todos ven lo mismo', benefit: 'Lo que anota cada persona llega a los demás teléfonos del negocio y queda respaldado. Si un teléfono se rompe, tus datos no se pierden.', steps: ['Mira el número de «Pendientes».', 'Si es mayor que cero, toca «Sincronizar ahora».', 'Cuando llegue a cero, todo está guardado.'], tip: '' },
  ],
  dependent: [
    { key: 'cash', title: 'Caja: empieza y termina el turno con las cuentas claras', benefit: 'Al empezar anotas el dinero que hay. Al terminar, la app calcula cuánto debería haber. Nadie tiene que poner dinero de su bolsillo por un error.', steps: ['Al empezar: escribe el efectivo que hay en la caja y toca «Abrir caja».', 'Al terminar: cuenta el efectivo y escribe las transferencias, gastos y retiros.', 'Toca «Enviar cierre al dueño».'], tip: 'Si pasó algo raro en el turno, escríbelo en «Observaciones». El dueño lo verá junto al cierre.' },
    { key: 'pos', title: 'Venta: cobrar en segundos', benefit: 'Buscas el producto, lo tocas y cobras. El precio sale solo y el inventario se descuenta solo. No hay que apuntar nada en papel.', steps: ['Escribe el nombre del producto o toca «Escanear».', 'Toca el producto para añadirlo a la venta.', 'Elige si te pagan en efectivo, por transferencia o mixto, y toca «Cobrar».'], tip: 'La app no deja vender más de lo que hay en el mostrador.' },
    { key: 'closeShift', title: 'Cierre diario: nada se queda sin contar', benefit: 'Al cerrar indicas qué quedó en el mostrador y si vuelve al almacén o se perdió. El dueño sabe exactamente qué pasó con cada producto.', steps: ['Revisa la cantidad que queda de cada producto.', 'Elige su destino: «Devolver al almacén», «Merma», «Daño» u «Otro».', 'Toca «Registrar cierre diario».'], tip: '' },
    { key: 'sync', title: 'Sincronización: tu trabajo llega al dueño', benefit: 'Tus ventas y cierres llegan al teléfono del dueño y quedan guardados.', steps: ['Mira el número de «Pendientes».', 'Si es mayor que cero, toca «Sincronizar ahora».', 'Cuando llegue a cero, todo está enviado.'], tip: '' },
  ],
};
const helpDay = [['Al abrir', 'El dependiente abre la caja con el efectivo inicial.'], ['Durante el día', 'Cada venta se cobra en la app. El inventario baja solo.'], ['Al cerrar', 'El dependiente cuenta la caja y envía el cierre.'], ['Después', 'Tú lo revisas desde tu teléfono y lo apruebas.']];
function help() {
  const role = state.helpRole || state.role;
  const guide = helpGuide[role];
  const labelOf = (key) => navItems().concat([['pos', 'Venta'], ['cash', 'Caja'], ['closeShift', 'Cierre diario']]).find(([k]) => k === key)?.[1] || key;
  const card = (item, index) => `<article class="help-card" id="ayuda-${item.key}">
    <figure class="help-shot"><img src="./ayuda/${role}-${item.key}.webp" alt="Pantalla ${escapeHtml(labelOf(item.key))} de Versa-Inventario" width="390" height="844" loading="lazy" decoding="async" /></figure>
    <div class="help-body">
      <p class="help-kicker">Paso ${index + 1} de ${guide.length}</p>
      <h2>${item.title}</h2>
      <p class="help-benefit">${item.benefit}</p>
      <h3>Cómo se usa</h3>
      <ol class="steps">${item.steps.map((step) => `<li>${step}</li>`).join('')}</ol>
      ${item.tip ? `<p class="help-tip"><strong>Consejo:</strong> ${item.tip}</p>` : ''}
      ${role === state.role ? `<button class="button secondary small" data-nav="${item.key}">Ir a ${escapeHtml(labelOf(item.key))} →</button>` : ''}
    </div>
  </article>`;
  return `${pageHead('Ayuda', 'Cada pantalla explicada en palabras simples. No necesitas saber de informática.')}
  ${panel('Tu día con Versa-Inventario', `<ol class="help-day">${helpDay.map(([when, what]) => `<li><strong>${when}</strong><span>${what}</span></li>`).join('')}</ol>`)}
  <div class="help-roles" role="tablist" aria-label="Elegir guía"><button role="tab" aria-selected="${role === 'owner'}" class="tab ${role === 'owner' ? 'active' : ''}" data-help-role="owner">Guía del dueño</button><button role="tab" aria-selected="${role === 'dependent'}" class="tab ${role === 'dependent' ? 'active' : ''}" data-help-role="dependent">Guía del dependiente</button></div>
  <nav class="help-index" aria-label="Pantallas">${guide.map((item) => `<button class="help-chip" data-help-jump="${item.key}">${escapeHtml(labelOf(item.key))}</button>`).join('')}</nav>
  <div class="help-list">${guide.map(card).join('')}</div>
  ${panel('¿Te quedó alguna duda?', '<p class="muted">Escríbenos y te lo explicamos por WhatsApp, con tu negocio como ejemplo.</p><a class="button" href="https://wa.me/5356189395?text=Hola%2C%20tengo%20una%20duda%20sobre%20Versa-Inventario" target="_blank" rel="noopener noreferrer">Preguntar por WhatsApp</a>')}`;
}
function tourModal() { const steps = state.role === 'owner' ? [['Productos', 'Primero crea o revisa los productos que venderá el negocio.', 'products'], ['Almacén', 'Registra entradas y pasa existencias al área de venta.', 'warehouse'], ['Oferta del día', 'Publica una oferta con sus precios y formas de pago.', 'offers'], ['Cierres', 'Al final del turno revisa el cierre enviado por el dependiente.', 'closures']] : [['Caja', 'Abre el turno con el efectivo inicial.', 'cash'], ['Venta', 'Busca un producto disponible, añádelo y cobra.', 'pos'], ['Sincronización', 'Revisa que las operaciones locales estén guardadas.', 'sync'], ['Ayuda', 'Consulta los pasos si olvidas qué hacer.', 'help']]; const step = steps[state.tourStep]; return `<div class="modal-backdrop"><div class="modal tour"><div class="tour-kicker">Guía inicial · ${state.tourStep + 1}/${steps.length}</div><h2>${step[0]}</h2><p>${step[1]}</p><div class="progress"><i style="width:${((state.tourStep + 1) / steps.length) * 100}%"></i></div><div class="modal-actions"><button class="button secondary" data-action="skip-tour">Saltar guía</button><button class="button" data-action="tour-next" data-tour-target="${step[2]}">${state.tourStep === steps.length - 1 ? 'Empezar' : 'Siguiente'}</button></div></div></div>`; }
function pdfPickerModal() { return `<div class="modal-backdrop"><div class="modal pdf-picker"><div class="tour-kicker">Seleccionar QR desde PDF</div><h2>${escapeHtml(state.pdfPicker.name)}</h2><p class="muted">Mueve o ajusta el marco para señalar el QR que quieres guardar. En esta demo la selección se conserva localmente.</p><div class="pdf-preview"><iframe title="Vista previa del PDF" src="${state.pdfPicker.url}"></iframe><div class="crop-frame"></div></div><div class="form-grid"><div class="field"><label>X</label><input class="input" data-crop="x" type="number" value="0" /></div><div class="field"><label>Y</label><input class="input" data-crop="y" type="number" value="0" /></div><div class="field"><label>Ancho</label><input class="input" data-crop="width" type="number" value="300" /></div><div class="field"><label>Alto</label><input class="input" data-crop="height" type="number" value="300" /></div></div><div class="modal-actions"><button class="button secondary" data-action="cancel-pdf">Cancelar</button><button class="button" data-action="accept-pdf">Aceptar QR seleccionado</button></div></div></div>`; }
function content() { const views = { home, products, warehouse, salesFloor, labels, offers, closures, reports, users, sync, pos, cash, closeShift, help }; return views[state.screen]?.() || views[state.role === 'owner' ? 'home' : 'pos'](); }
document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && state.menuOpen) { state.menuOpen = false; render(); document.querySelector('[data-action="open-menu"]')?.focus(); } });
function render() { app.innerHTML = layout(content()); bind(); }
function formData(form) { return Object.fromEntries(new FormData(form).entries()); }
function bind() {
  document.querySelectorAll('[data-role]').forEach((b) => b.addEventListener('click', async () => { state.role = b.dataset.role; state.helpRole = null; state.menuOpen = false; state.screen = state.role === 'owner' ? 'home' : 'pos'; state.query = ''; const settings = (await readAll('settings')).find((s) => s.id === 'tour'); if (!settings?.completed) { state.tour = true; state.tourStep = 0; } render(); }));
  document.querySelectorAll('[data-nav]').forEach((b) => b.addEventListener('click', () => { state.screen = b.dataset.nav; state.query = ''; state.menuOpen = false; render(); window.scrollTo(0, 0); }));
  document.querySelector('[data-action="open-menu"]')?.addEventListener('click', () => { state.menuOpen = true; render(); document.querySelector('.drawer-close')?.focus(); });
  document.querySelectorAll('[data-action="close-menu"]').forEach((b) => b.addEventListener('click', () => { state.menuOpen = false; render(); }));
  document.querySelectorAll('[data-query]').forEach((input) => input.addEventListener('input', () => { state.query = input.value; render(); const focused = document.querySelector('[data-query]'); focused?.focus(); focused?.setSelectionRange(state.query.length, state.query.length); }));
  document.querySelectorAll('[data-warehouse-tab]').forEach((b) => b.addEventListener('click', () => { state.warehouseTab = b.dataset.warehouseTab; render(); }));
  document.querySelectorAll('[data-catalog-select]').forEach((select) => select.addEventListener('change', () => { if (select.value !== '__new__') return; const label = select.dataset.catalogSelect === 'presentation' ? 'Escribe la nueva presentación' : 'Escribe la nueva unidad'; const next = window.prompt(label); if (!next?.trim()) { render(); return; } const value = next.trim(); const target = select.dataset.catalogSelect === 'presentation' ? state.presentations : state.units; if (!target.includes(value)) target.push(value); const form = select.closest('form'); if (form && state.productEditor) state.productEditor = { ...state.productEditor, ...formData(form), [select.name]: value }; render(); const fresh = document.querySelector(`[data-catalog-select="${select.dataset.catalogSelect}"]`); if (fresh) fresh.value = value; }));
  document.querySelectorAll('[data-help-role]').forEach((b) => b.addEventListener('click', () => { state.helpRole = b.dataset.helpRole; render(); document.querySelector('.help-roles')?.scrollIntoView({ block: 'start' }); }));
  document.querySelectorAll('[data-help-jump]').forEach((b) => b.addEventListener('click', () => document.getElementById(`ayuda-${b.dataset.helpJump}`)?.scrollIntoView({ behavior: 'smooth', block: 'start' })));
  document.querySelector('[data-action="new-product"]')?.addEventListener('click', () => { state.productEditor = {}; render(); });
  document.querySelector('[data-action="close-editor"]')?.addEventListener('click', () => { state.productEditor = null; render(); });
  document.querySelectorAll('[data-action="edit-product"]').forEach((b) => b.addEventListener('click', () => { state.productEditor = state.products.find((p) => p.id === b.dataset.id); render(); }));
  document.querySelector('[data-form="product"]')?.addEventListener('submit', async (e) => { e.preventDefault(); const values = formData(e.currentTarget); const existing = state.productEditor?.id; const product = { ...(state.productEditor || {}), id: existing || id('product'), name: values.name.trim(), sku: values.sku.trim() || id('sku'), presentation: values.presentation, unit: values.unit, priceCash: Number(values.priceCash || 0), priceTransfer: Number(values.priceTransfer || values.priceCash || 0), cost: Number(values.cost || 0), minStock: Number(values.minStock || 0), stock: state.productEditor?.stock || 0, warehouse: state.productEditor?.warehouse || 0, salesFloor: state.productEditor?.salesFloor || 0 }; await put('products', product); await reloadData(); state.productEditor = null; showToast(existing ? 'Producto actualizado.' : 'Producto guardado.'); });
  document.querySelector('[data-action="warehouse-save"]')?.addEventListener('click', async (e) => { const type = e.currentTarget.dataset.type; const productId = document.querySelector('[data-warehouse-product]')?.value; const qtyInput = [...document.querySelectorAll('.subpanel input')].find((x) => x.name.includes('cantidad')); const quantity = Number(qtyInput?.value || 0); const product = state.products.find((p) => p.id === productId); if (!product) { showToast('Elige un producto.'); return; } if (quantity <= 0) { showToast('Escribe una cantidad mayor que cero.'); return; } if (type !== 'incoming' && quantity > product.warehouse) { showToast(`No se puede mover: solo quedan ${product.warehouse} en almacén.`); return; } if (type === 'incoming') { product.stock += quantity; product.warehouse += quantity; } if (type === 'transfer') { product.warehouse -= quantity; product.salesFloor += quantity; } if (type === 'loss') { product.warehouse -= Math.min(quantity, product.warehouse); product.stock -= Math.min(quantity, product.stock); } await put('products', product); await put('movements', { id: id('movement'), summary: `${type}: ${product.name} · ${quantity}`, status: 'pending', createdAt: new Date().toISOString() }); await reloadData(); showToast('Movimiento guardado.'); });
  document.querySelectorAll('[data-label-id]').forEach((c) => c.addEventListener('change', () => { state.labelIds = c.checked ? [...new Set([...state.labelIds, c.dataset.labelId])] : state.labelIds.filter((idValue) => idValue !== c.dataset.labelId); render(); }));
  document.querySelector('[data-action="select-all"]')?.addEventListener('click', () => { const visible = state.products.filter((p) => !state.query || `${p.name} ${p.sku}`.toLowerCase().includes(state.query.toLowerCase())); const all = visible.every((p) => state.labelIds.includes(p.id)); state.labelIds = all ? state.labelIds.filter((idValue) => !visible.some((p) => p.id === idValue)) : [...new Set([...state.labelIds, ...visible.map((p) => p.id)])]; render(); });
  document.querySelector('[data-action="print-labels"]')?.addEventListener('click', async () => { for (const p of state.products.filter((x) => state.labelIds.includes(x.id))) await put('labels', { id: id('label'), name: p.name, sku: p.sku, qr: `versa-inventario://${p.id}`, createdAt: new Date().toISOString() }); await reloadData(); showToast('Etiquetas guardadas para imprimir.'); });
  document.querySelector('[data-offer-product]')?.addEventListener('change', (e) => { const p = state.products.find((x) => x.id === e.target.value); if (!p) return; document.querySelector('[data-offer-cash]').value = p.priceCash; document.querySelector('[data-offer-transfer]').value = p.priceTransfer; document.querySelector('[data-offer-sale-cash]').value = p.priceCash; document.querySelector('[data-offer-sale-transfer]').value = p.priceTransfer; });
  document.querySelector('[data-action="save-offer"]')?.addEventListener('click', async () => { const productId = document.querySelector('[data-offer-product]').value; const p = state.products.find((x) => x.id === productId); if (!p) { showToast('Selecciona un producto para la oferta.'); return; } await put('offers', { id: 'current-offer', productId, productName: p.name, priceCash: Number(document.querySelector('[data-offer-cash]').value), priceTransfer: Number(document.querySelector('[data-offer-transfer]').value), offerCash: Number(document.querySelector('[data-offer-sale-cash]').value), offerTransfer: Number(document.querySelector('[data-offer-sale-transfer]').value), message: document.querySelector('[data-offer-message]').value, payments: { cash: document.querySelector('[data-pay="cash"]').checked, transfer: document.querySelector('[data-pay="transfer"]').checked }, createdAt: new Date().toISOString(), active: true }); await reloadData(); showToast('Oferta publicada en la demo local.'); });
  document.querySelectorAll('input[type="file"]').forEach((input) => input.addEventListener('change', () => { const file = input.files?.[0]; const target = document.querySelector(`[data-file-name="${input.dataset.file}"]`); if (target && file) target.textContent = `${file.name} · seleccionado`; if (file && input.dataset.file === 'qr' && file.type === 'application/pdf') { state.pdfPicker = { name: file.name, url: URL.createObjectURL(file) }; render(); } }));
  document.querySelector('[data-action="cancel-pdf"]')?.addEventListener('click', () => { if (state.pdfPicker?.url) URL.revokeObjectURL(state.pdfPicker.url); state.pdfPicker = null; render(); });
  document.querySelector('[data-action="accept-pdf"]')?.addEventListener('click', async () => { const crop = Object.fromEntries([...document.querySelectorAll('[data-crop]')].map((input) => [input.dataset.crop, Number(input.value || 0)])); await put('settings', { id: 'transfer_qr_pdf', fileName: state.pdfPicker.name, crop, selectedAt: new Date().toISOString() }); if (state.pdfPicker?.url) URL.revokeObjectURL(state.pdfPicker.url); state.pdfPicker = null; render(); showToast('QR seleccionado desde el PDF y guardado localmente.'); });
  document.querySelector('[data-action="save-assets"]')?.addEventListener('click', async () => { await put('settings', { id: 'transfer_info', account: document.querySelector('[data-asset="account"]').value.trim(), phone: document.querySelector('[data-asset="phone"]').value.trim() }); await reloadData(); showToast('Información de cobros guardada localmente.'); });
  document.querySelectorAll('[data-action="approve"], [data-action="reject"]').forEach((b) => b.addEventListener('click', async () => { const shift = state.shifts.find((s) => s.id === b.dataset.id); shift.status = b.dataset.action === 'approve' ? 'approved' : 'rejected'; await put('shifts', shift); await reloadData(); showToast(shift.status === 'approved' ? 'Cierre aprobado.' : 'Cierre rechazado.'); }));
  document.querySelector('[data-action="toggle-details"]')?.addEventListener('click', () => { state.reportDetails = !state.reportDetails; render(); });
  document.querySelector('[data-action="new-user"]')?.addEventListener('click', () => { state.userEditor = true; render(); });
  document.querySelector('[data-form="user"]')?.addEventListener('submit', async (e) => { e.preventDefault(); const v = formData(e.currentTarget); await put('users', { id: id('user'), name: v.name, email: v.email, point: v.point, role: 'Dependiente' }); await reloadData(); state.userEditor = false; showToast('Dependiente creado localmente.'); });
  document.querySelector('[data-action="sync"]')?.addEventListener('click', async () => { for (const m of state.movements) { m.status = 'synced'; await put('movements', m); } await reloadData(); showToast('Sincronización demo completada.'); });
  document.querySelectorAll('[data-action="add-cart"]').forEach((b) => b.addEventListener('click', () => { const p = state.products.find((x) => x.id === b.dataset.id); const item = state.cart.find((x) => x.id === p.id); const inCart = item?.quantity || 0; if (inCart >= p.salesFloor) { showToast(`Solo hay ${p.salesFloor} de ${p.name} en el área de venta.`); return; } if (item) item.quantity += 1; else state.cart.push({ ...p, quantity: 1 }); render(); }));
  document.querySelectorAll('[data-action="remove-cart"]').forEach((b) => b.addEventListener('click', () => { state.cart = state.cart.filter((x) => x.id !== b.dataset.id); render(); }));
  document.querySelector('[data-action="scan"]')?.addEventListener('click', () => showToast('En la app instalada, aquí se abre la cámara para escanear la etiqueta QR.'));
  document.querySelector('[data-action="charge"]')?.addEventListener('click', async () => { const shift = state.shifts.find((s) => s.status === 'open'); if (!shift) { showToast('Abre la caja antes de cobrar.'); return; } const payment = document.querySelector('[data-payment]').value; const total = state.cart.reduce((sum, i) => sum + (payment === 'transfer' ? i.priceTransfer : i.priceCash) * i.quantity, 0); let cashPart = payment === 'cash' ? total : 0; let transferPart = payment === 'transfer' ? total : 0; if (payment === 'mixed') { cashPart = Number(document.querySelector('[data-cash-payment]').value || 0); transferPart = Number(document.querySelector('[data-transfer-payment]').value || 0); if (cashPart + transferPart !== total) { showToast(`Efectivo + transferencia debe sumar ${money(total)}.`); return; } } const sale = { id: id('sale'), summary: state.cart.map((i) => `${i.name} x${i.quantity}`).join(', '), total, payment, cash: cashPart, transfer: transferPart, shiftId: shift.id, createdAt: new Date().toISOString() }; await put('sales', sale); shift.expectedCash = Number(shift.expectedCash || 0) + cashPart; shift.expectedTransfer = Number(shift.expectedTransfer || 0) + transferPart; await put('shifts', shift); for (const item of state.cart) { const p = state.products.find((x) => x.id === item.id); p.salesFloor = Math.max(0, p.salesFloor - item.quantity); p.stock = Math.max(0, p.stock - item.quantity); await put('products', p); } state.cart = []; await reloadData(); showToast('Venta guardada.'); });
  document.querySelector('[data-action="cash-toggle"]')?.addEventListener('click', async () => { const open = state.shifts.find((s) => s.status === 'open'); if (open) { open.declaredCash = Number(document.querySelector('[data-cash]').value || 0); open.declaredTransfer = Number(document.querySelector('[data-transfer]').value || 0); open.expenses = Number(document.querySelector('[data-expenses]').value || 0); open.withdrawals = Number(document.querySelector('[data-withdrawals]').value || 0); open.notes = document.querySelector('[data-notes]').value.trim(); open.expectedCash = Number(open.expectedCash || 0) - open.expenses - open.withdrawals; open.difference = open.declaredCash + open.declaredTransfer - open.expectedCash - Number(open.expectedTransfer || 0); open.status = 'pending_review'; await put('shifts', open); await reloadData(); showToast('Cierre enviado al dueño.'); } else { const opening = Number(document.querySelector('[data-opening]').value || 0); await put('shifts', { id: id('shift'), dependent: 'Leidis', status: 'open', openingCash: opening, expectedCash: opening, declaredCash: 0, declaredTransfer: 0, difference: 0, date: new Date().toISOString().slice(0, 10) }); await reloadData(); showToast('Caja abierta.'); } });
  document.querySelector('[data-action="close-shift"]')?.addEventListener('click', async () => { for (const p of state.products) { const qty = Math.min(Number(document.querySelector(`[data-close-qty="${p.id}"]`)?.value || 0), p.salesFloor); if (qty <= 0) continue; const destination = document.querySelector(`[data-close-destination="${p.id}"]`).value; p.salesFloor -= qty; if (destination === 'warehouse') p.warehouse += qty; else p.stock -= qty; await put('products', p); const note = document.querySelector(`[data-close-note="${p.id}"]`).value.trim(); await put('movements', { id: id('movement'), summary: `closing: ${p.name} · ${qty} → ${destination === 'warehouse' ? 'almacén' : 'pérdida'}${note ? ` (${note})` : ''}`, status: 'pending', createdAt: new Date().toISOString() }); } await reloadData(); showToast('Cierre diario registrado en la demo local.'); });
  document.querySelector('[data-action="skip-tour"]')?.addEventListener('click', async () => { await put('settings', { id: 'tour', completed: true }); state.tour = null; render(); });
  document.querySelector('[data-action="tour-next"]')?.addEventListener('click', async (e) => { const stepsCount = 4; const target = e.currentTarget.dataset.tourTarget; if (state.tourStep >= stepsCount - 1) { await put('settings', { id: 'tour', completed: true }); state.tour = null; state.screen = target; render(); } else { state.tourStep += 1; render(); } });
}
